import random
from collections import Counter
from functools import lru_cache
from itertools import combinations

PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}

def dp_tops(basket):
    counts = sorted(Counter(basket).values(), reverse=True)
    while len(counts) < 5:
        counts.append(0)
    @lru_cache(maxsize=None)
    def solve(c):
        if c[0] == 0:
            return 0
        best = 800 * sum(c)
        for size in range(1, 6):
            if c[size - 1] > 0:
                nc = list(c)
                for i in range(size):
                    nc[i] -= 1
                nc = tuple(sorted(nc, reverse=True))
                best = min(best, PRICES[size] + solve(nc))
        return best
    return solve(tuple(counts))

def dp_full(basket):
    # allow a group to draw from ANY subset of titles (not just top s)
    counts = sorted(Counter(basket).values(), reverse=True)
    while len(counts) < 5:
        counts.append(0)
    @lru_cache(maxsize=None)
    def solve(c):
        if c[0] == 0:
            return 0
        best = 800 * sum(c)
        c = list(c)
        for size in range(1, 6):
            for idxs in combinations(range(5), size):
                if all(c[i] > 0 for i in idxs):
                    nc = list(c)
                    for i in idxs:
                        nc[i] -= 1
                    nc = tuple(sorted(nc, reverse=True))
                    best = min(best, PRICES[size] + solve(nc))
        return best
    return solve(tuple(counts))

random.seed(42)
mismatch = 0
for trial in range(400):
    n = random.randint(0, 12)
    basket = [random.randint(1, 5) for _ in range(n)]
    a, b = dp_tops(basket), dp_full(basket)
    if a != b:
        mismatch += 1
        print("MISMATCH", basket, "tops=", a, "full=", b)
print("done, mismatches:", mismatch)
